insert into public.towns (name, slug, province, description, latitude, longitude, kind, radius_km, cover_image_url, cover_image_credit, cover_image_license, cover_image_source_url, wiki_url) values
  ('Mabopane', 'mabopane', 'Gauteng', 'Mabopane is a large residential township located about 22 km north-west of Pretoria, within the City of Tshwane Metropolitan Municipality in Gauteng, South Africa. The 2011 census counted roughly 110,972 residents, predominantly Setswana speakers.', -25.508056, 28.068056, 'suburb', 3.5, null, null, null, null, 'https://en.wikipedia.org/wiki/Mabopane'),
  ('Soshanguve', 'soshanguve', 'Gauteng', 'Soshanguve is a township situated about 30 km north of Pretoria and just east of Mabopane, in Gauteng, South Africa. The name Soshanguve is an acronym for Sotho, Shangaan, Nguni and Venda, thus showing the multi-ethnic composition of the population.', -25.526389, 28.099444, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Soshanguve_Crossing.jpg/1920px-Soshanguve_Crossing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Thulani Godfrey Timba', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Soshanguve_Crossing.jpg', 'https://en.wikipedia.org/wiki/Soshanguve'),
  ('Ga-Rankuwa', 'ga-rankuwa', 'Gauteng', 'Ga-Rankuwa is a large settlement located about 37 km north-west of Pretoria. Provincially it is in Gauteng province, but it used to fall in Bophuthatswana during the apartheid years, and under the North West province until the early 2000s.', -25.588446, 28.007511, 'town', 5, null, null, null, null, 'https://en.wikipedia.org/wiki/Ga-Rankuwa'),
  ('Pretoria', 'pretoria', 'Gauteng', 'Pretoria is the executive capital of South Africa, serving as the seat of the executive branch of government, and as the host to all foreign embassies to the country.', -25.745928, 28.18791, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/6/6b/Uniegebou.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Davinci77', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Uniegebou.jpg', 'https://en.wikipedia.org/wiki/Pretoria'),
  ('Johannesburg', 'johannesburg', 'Gauteng', 'Johannesburg, colloquially known as Jozi, Joburg, or "the City of Gold", is the capital city of the province of Gauteng and the largest city in South Africa. In 2022, the City of Johannesburg Metropolitan Municipality had a population of 4,803,262, and the wider metropolitan area a population of 15,099,422, making it one of the 100 largest urban areas in the world.', -26.205, 28.049722, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Johannesburg_skyline_2017.jpg/1920px-Johannesburg_skyline_2017.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Mark Hillary', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Johannesburg_skyline_2017.jpg', 'https://en.wikipedia.org/wiki/Johannesburg'),
  ('Midrand', 'midrand', 'Gauteng', 'Midrand is an area in central Gauteng, South Africa. It is situated in-between Centurion and Sandton.', -25.999262, 28.125912, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Johhanesburg_Water-Midrand_Tower-002.jpg/1920px-Johhanesburg_Water-Midrand_Tower-002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'NJR ZA', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Johhanesburg_Water-Midrand_Tower-002.jpg', 'https://en.wikipedia.org/wiki/Midrand'),
  ('Centurion', 'centurion', 'Gauteng', 'Centurion is an area with 236,580 inhabitants in the Gauteng Province of South Africa, between Pretoria and Midrand. Formerly an independent municipality, with its own town council, it has been part of the City of Tshwane Metropolitan Municipality since 2000.', -25.836389, 28.180278, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/CenturionGautrainStation.jpg/1920px-CenturionGautrainStation.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'George Thomas Stevenson', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:CenturionGautrainStation.jpg', 'https://en.wikipedia.org/wiki/Centurion%2C_South_Africa'),
  ('Rustenburg', 'rustenburg', 'North West', 'Rustenburg is a City at the foot of the Magaliesberg mountain range. Rustenburg is the most populous city in North West province, South Africa.', -25.665655, 27.241448, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Kruger_Statue_-_Rustenburg.jpeg/1920px-Kruger_Statue_-_Rustenburg.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Fritz Joubert', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Kruger_Statue_-_Rustenburg.jpeg', 'https://en.wikipedia.org/wiki/Rustenburg'),
  ('Polokwane', 'polokwane', 'Limpopo', 'Polokwane, formerly and sometimes also known as Pietersburg, is the capital city of the Limpopo Province of South Africa. It is the country''s largest urban centre north of Gauteng.', -23.905833, 29.461389, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Polokwane%2C_Limpopo%2C_South_Africa_%282417714241%29.jpg/1920px-Polokwane%2C_Limpopo%2C_South_Africa_%282417714241%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Polokwane,_Limpopo,_South_Africa_(2417714241).jpg', 'https://en.wikipedia.org/wiki/Polokwane'),
  ('Durban', 'durban', 'KwaZulu-Natal', 'Durban is the third-most populous city in South Africa, after Johannesburg and Cape Town, and the largest city in the province of KwaZulu-Natal. Situated on the east coast of South Africa, on the Natal Bay of the Indian Ocean, Durban is the busiest port city in sub-Saharan Africa and was formerly named Port Natal.', -29.861815, 31.009909, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Durban_from_the_Balcony_%28Dennis_Sylvester_Hurd%29_1.jpg/1920px-Durban_from_the_Balcony_%28Dennis_Sylvester_Hurd%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Dennis Sylvester Hurd', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Durban_from_the_Balcony_(Dennis_Sylvester_Hurd)_1.jpg', 'https://en.wikipedia.org/wiki/Durban'),
  ('Cape Town', 'cape-town', 'Western Cape', 'Cape Town is the legislative capital of South Africa. It is the country''s oldest city and the seat of the Parliament of South Africa.', -33.92883, 18.41722, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Camps_bay_%2853460319478%29_%28cropped%29.jpg/1920px-Camps_bay_%2853460319478%29_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Der Berzerker from Washington, DC, USA', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Camps_bay_(53460319478)_(cropped).jpg', 'https://en.wikipedia.org/wiki/Cape_Town'),
  ('Akasia', 'akasia', 'Gauteng', null, -25.655556, 28.096944, 'town', 5, null, null, null, null, null),
  ('Hammanskraal', 'hammanskraal', 'Gauteng', 'Hammanskraal is a trans-provincial region anchored in northern Gauteng province, South Africa. The region consists of multiple residential, industrial, and commercial areas in a decentralized settlement pattern.', -25.408333, 28.287222, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Hammanskraal%2C_besigheidsdistrik.jpg/1920px-Hammanskraal%2C_besigheidsdistrik.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'JMK', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Hammanskraal,_besigheidsdistrik.jpg', 'https://en.wikipedia.org/wiki/Hammanskraal'),
  ('Winterveldt', 'winterveldt', 'Gauteng', null, -25.488295, 28.073111, 'suburb', 3.5, null, null, null, null, null),
  ('Mamelodi', 'mamelodi', 'Gauteng', 'Mamelodi is a township northeast of Pretoria, Gauteng, South Africa. A part of the City of Tshwane Metropolitan Municipality, it was set up by the then apartheid government in 1953.', -25.715805, 28.38083, 'town', 5, 'https://upload.wikimedia.org/wikipedia/commons/3/30/Mamelodi.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', null, 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Mamelodi.JPG', 'https://en.wikipedia.org/wiki/Mamelodi'),
  ('Atteridgeville', 'atteridgeville', 'Gauteng', 'Atteridgeville, also known as Phelindaba, is a township located to the west of Pretoria, South Africa. The township was established in 1939 and is named after Mrs MP Atteridge (1900-1979), chairwoman of the Committee for Non-European Affairs on the Pretoria City Council at the time.', -25.771389, 28.073611, 'suburb', 3.5, null, null, null, null, 'https://en.wikipedia.org/wiki/Atteridgeville'),
  ('Hatfield', 'hatfield', 'Gauteng', 'Hatfield is a suburb in Pretoria, South Africa with a high density of students as well as student accommodation due to its close proximity to the University of Pretoria''s main campus.', -25.74764, 28.237873, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Die_skip_University_of_pretoria.JPG/1920px-Die_skip_University_of_pretoria.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Mike-Prins', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Die_skip_University_of_pretoria.JPG', 'https://en.wikipedia.org/wiki/Hatfield%2C_Pretoria'),
  ('Soweto', 'soweto', 'Gauteng', 'Soweto is a township of the City of Johannesburg Metropolitan Municipality in Gauteng, South Africa and one of the suburbs of Johannesburg, bordering the city''s mining belt in the south. Its name is an English syllabic abbreviation for South Western Townships.', -26.222778, 27.89, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Soweto-002.jpg/1920px-Soweto-002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Michael Denne from Hobart, Australia', 'CC BY-SA 2.0', 'https://commons.wikimedia.org/wiki/File:Soweto-002.jpg', 'https://en.wikipedia.org/wiki/Soweto'),
  ('Sandton', 'sandton', 'Gauteng', null, -26.068241, 28.047984, 'suburb', 3.5, null, null, null, null, null),
  ('Randburg', 'randburg', 'Gauteng', 'Randburg is an area located in the Gauteng province of South Africa. Formerly a separate municipality, its administration devolved to the newly created City of Johannesburg Metropolitan Municipality, along with neighbouring Sandton and Roodepoort, in the late 1990s.', -26.091585, 28.002028, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/d/d5/MotoPops_-_Beverley_Gardens%2C_Randburg%2C_South_Africa.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'MotoPops', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:MotoPops_-_Beverley_Gardens,_Randburg,_South_Africa.jpg', 'https://en.wikipedia.org/wiki/Randburg'),
  ('Roodepoort', 'roodepoort', 'Gauteng', 'Roodepoort is a city in the Gauteng province of South Africa. Formerly an independent municipality, Roodepoort became part of the Johannesburg municipality in the late 1990s, along with Randburg and Sandton.', -26.156663, 27.885565, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Bastion_Ho%C3%ABrskool%2C_Roodepoort.jpg/1920px-Bastion_Ho%C3%ABrskool%2C_Roodepoort.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'JMK', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Bastion_Ho%C3%ABrskool,_Roodepoort.jpg', 'https://en.wikipedia.org/wiki/Roodepoort'),
  ('Tembisa', 'tembisa', 'Gauteng', 'Thembisa, formerly Tembisa, is a large township situated to the north of Kempton Park on the East Rand, Gauteng, South Africa. It was established in 1957 when black people were resettled from Alexandra and other areas in Edenvale, Kempton Park, Midrand and Germiston.', -26.009715, 28.231461, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Lazarus_Mawela_Station-Tembisa.png/1920px-Lazarus_Mawela_Station-Tembisa.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Thuvack', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Lazarus_Mawela_Station-Tembisa.png', 'https://en.wikipedia.org/wiki/Thembisa'),
  ('Alexandra', 'alexandra', 'Gauteng', 'Alexandra, informally abbreviated to Alex, is a township in the Gauteng province of South Africa. It forms part of the City of Johannesburg Metropolitan Municipality and is located next to the wealthy suburb of Sandton.', -26.104444, 28.098889, 'suburb', 3.5, null, null, null, null, 'https://en.wikipedia.org/wiki/Alexandra%2C_South_Africa'),
  ('Diepsloot', 'diepsloot', 'Gauteng', 'Diepsloot, Afrikaans for "deep ditch", is a densely populated township in Gauteng, South Africa. It is located in the Region A of the City of Johannesburg Metropolitan Municipality.', -25.93095, 28.01059, 'suburb', 3.5, 'https://upload.wikimedia.org/wikipedia/commons/3/3e/Wassup_activists_say_the_government_should_do_more_to_maintain_the_community%27s_environment_in_Diepsloot%2C_South_Africa%2C_December_2012._%28VOA_S._Honorine%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'VOA S. Honorine', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Wassup_activists_say_the_government_should_do_more_to_maintain_the_community%27s_environment_in_Diepsloot,_South_Africa,_December_2012._(VOA_S._Honorine).jpg', 'https://en.wikipedia.org/wiki/Diepsloot'),
  ('Kempton Park', 'kempton-park', 'Gauteng', 'Kempton Park is a city in the East Rand region of Gauteng province, South Africa. It is part of the City of Ekurhuleni Metropolitan Municipality.', -26.096437, 28.233632, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Kempton_Park_CBD.jpg/1920px-Kempton_Park_CBD.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'PretoriaTravel', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Kempton_Park_CBD.jpg', 'https://en.wikipedia.org/wiki/Kempton_Park%2C_Gauteng'),
  ('Benoni', 'benoni', 'Gauteng', 'Benoni is a town on the East Rand, Gauteng, South Africa, some 26 kilometres (16 mi) east of Johannesburg, within the City of Ekurhuleni municipality.', -26.193036, 28.308238, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Benoni_CBD.jpg/1920px-Benoni_CBD.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'PretoriaTravel', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Benoni_CBD.jpg', 'https://en.wikipedia.org/wiki/Benoni%2C_South_Africa'),
  ('Boksburg', 'boksburg', 'Gauteng', 'Boksburg is a city on the East Rand of Gauteng province of South Africa. Gold was discovered in Boksburg in 1887.', -26.212464, 28.261747, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Into_Boksburg_and_ERM.jpg/1920px-Into_Boksburg_and_ERM.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Part Time Security', 'Public domain', 'https://commons.wikimedia.org/wiki/File:Into_Boksburg_and_ERM.jpg', 'https://en.wikipedia.org/wiki/Boksburg'),
  ('Germiston', 'germiston', 'Gauteng', 'Germiston, also known as kwaDukathole, is a city in the East Rand region of Gauteng, South Africa, administratively forming part of the City of Ekurhuleni Metropolitan Municipality since the latter''s establishment in 2000. It functions as the municipal seat of Ekurhuleni, hosting the municipal council and administration.', -26.229444, 28.180556, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Germiston_CBD.jpg/1920px-Germiston_CBD.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'PretoriaTravel', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Germiston_CBD.jpg', 'https://en.wikipedia.org/wiki/Germiston'),
  ('Krugersdorp', 'krugersdorp', 'Gauteng', 'Krugersdorp is a mining city in the West Rand, Gauteng Province, South Africa founded in 1887 by Marthinus Pretorius and Abner Cohen. Following the discovery of gold on the Witwatersrand, a need arose for a major town in the west of the reef.', -26.095556, 27.775556, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Featherbrooke-landgoed%2C_Krugersdorp.jpg/1920px-Featherbrooke-landgoed%2C_Krugersdorp.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'JMK', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Featherbrooke-landgoed,_Krugersdorp.jpg', 'https://en.wikipedia.org/wiki/Krugersdorp'),
  ('Vereeniging', 'vereeniging', 'Gauteng', 'Vereeniging is a city located in the south of Gauteng province, South Africa, situated where the Klip River empties into the northern loop of the Vaal River. It is also one of the constituent parts of the Vaal Triangle region and was formerly situated in the Transvaal province.', -26.674722, 27.926111, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/b/bb/Dutch_Reformed_Church_Vereeniging-017.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Leo za1', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Dutch_Reformed_Church_Vereeniging-017.jpg', 'https://en.wikipedia.org/wiki/Vereeniging'),
  ('Brits', 'brits', 'North West', 'Brits is a town in the North West Province of South Africa. It is situated in a fertile citrus, vegetable and grain-producing area that is irrigated by the waters of the Hartbeespoort Dam.', -25.629722, 27.784167, 'town', 5, 'https://upload.wikimedia.org/wikipedia/commons/4/49/Brits%2C_Noordwes%2C_uit_suidweste.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'JMK', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Brits,_Noordwes,_uit_suidweste.jpg', 'https://en.wikipedia.org/wiki/Brits%2C_South_Africa'),
  ('Hartbeespoort', 'hartbeespoort', 'North West', 'Hartbeespoort, informally known as "Harties", is a small resort town in the North West Province of South Africa, situated on slopes of the Magaliesberg mountain and the banks of the Hartbeespoort Dam. The name of the town means "gateway of the hartbees" in Afrikaans.', -25.725617, 27.848319, 'suburb', 3.5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hartbeespoort_Dam_Wall%2C_North_West%2C_South_Africa_%2820329599590%29.jpg/1920px-Hartbeespoort_Dam_Wall%2C_North_West%2C_South_Africa_%2820329599590%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Hartbeespoort_Dam_Wall,_North_West,_South_Africa_(20329599590).jpg', 'https://en.wikipedia.org/wiki/Hartbeespoort'),
  ('Mahikeng', 'mahikeng', 'North West', 'Mafikeng, officially known as Mahikeng and alternatively known as Mafeking, is the capital city of the North West province of South Africa. It was also the capital of the Bechuanaland Protectorate until 1965, despite being located outside the protectorate.', -25.863611, 25.658611, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Mafikeng%2C_North_West%2C_South_Africa_%2820506154516%29.jpg/1920px-Mafikeng%2C_North_West%2C_South_Africa_%2820506154516%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Mafikeng,_North_West,_South_Africa_(20506154516).jpg', 'https://en.wikipedia.org/wiki/Mafikeng'),
  ('Potchefstroom', 'potchefstroom', 'North West', 'Potchefstroom, known colloquially as Potch, is an academic city in the North West Province of South Africa. It hosts the Potchefstroom Campus of North-West University.', -26.707778, 27.095833, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Town_Hall%2C_Potgieter_Street%2C_Potchefstroom-001.jpg/1920px-Town_Hall%2C_Potgieter_Street%2C_Potchefstroom-001.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Leo za1', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Town_Hall,_Potgieter_Street,_Potchefstroom-001.jpg', 'https://en.wikipedia.org/wiki/Potchefstroom'),
  ('Klerksdorp', 'klerksdorp', 'North West', 'Klerksdorp is located in the North West Province, South Africa. Klerksdorp is located 165 km (103 mi) southeast of Mahikeng, the provincial capital.', -26.862538, 26.665681, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/1/11/Municipal_Office_of_the_City_of_Matlosana_Local_Municipality.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'WalVlekkie', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Municipal_Office_of_the_City_of_Matlosana_Local_Municipality.jpg', 'https://en.wikipedia.org/wiki/Klerksdorp'),
  ('Thohoyandou', 'thohoyandou', 'Limpopo', 'Thohoyandou is a town in the Limpopo Province of South Africa. It is the administrative centre of Vhembe District Municipality and Thulamela Local Municipality.', -22.967643, 30.459658, 'town', 5, 'https://upload.wikimedia.org/wikipedia/commons/8/8b/Thohoyandou_Venda_Plaza.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Ndivhuwo Rannenyeni', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Thohoyandou_Venda_Plaza.jpg', 'https://en.wikipedia.org/wiki/Thohoyandou'),
  ('Tzaneen', 'tzaneen', 'Limpopo', 'Tzaneen is a town in the Mopani district of Limpopo Province in South Africa. Situated in a high rainfall very fertile area with tropical and subtropical agriculture with an area of 20,000 square kilometres (7,700 sq mi).', -23.831944, 30.161111, 'town', 5, 'https://upload.wikimedia.org/wikipedia/commons/9/9f/Tzaneen_tea_plants.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Rob Hooft', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Tzaneen_tea_plants.jpg', 'https://en.wikipedia.org/wiki/Tzaneen'),
  ('Mbombela', 'mbombela', 'Mpumalanga', 'Mbombela, formerly Nelspruit, is a city in northeastern South Africa. It is the capital of the Mpumalanga province.', -25.472909, 30.977272, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/NelspruitPanorama.JPG/1920px-NelspruitPanorama.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Wernermeiringvdm at English Wikipedia', 'CC BY 3.0', 'https://commons.wikimedia.org/wiki/File:NelspruitPanorama.JPG', 'https://en.wikipedia.org/wiki/Mbombela'),
  ('eMalahleni', 'emalahleni', 'Mpumalanga', 'Witbank, officially eMalahleni, is a city located on the Highveld of Mpumalanga, South Africa, within the Emalahleni Local Municipality. The name Witbank is Afrikaans for "white ridge", and is named after a white sandstone outcrop where wagon transport drivers rested.', -25.876241, 29.209996, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/e/e2/South_Africa-Mpumalanga-Witbank01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Gerhard Roux &lt;gerhard@sundown.homeip.net&gt;', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:South_Africa-Mpumalanga-Witbank01.jpg', 'https://en.wikipedia.org/wiki/Witbank'),
  ('Pietermaritzburg', 'pietermaritzburg', 'KwaZulu-Natal', 'Pietermaritzburg is the capital and second-largest city in the province of KwaZulu-Natal, South Africa after Durban. It was named in 1838 and is currently governed by the Msunduzi Local Municipality.', -29.6, 30.378889, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/0/0c/00000-St_Peters_Church2-Pietermaritzburg-s.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Janek Szymanowski', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:00000-St_Peters_Church2-Pietermaritzburg-s.jpg', 'https://en.wikipedia.org/wiki/Pietermaritzburg'),
  ('Umhlanga', 'umhlanga', 'KwaZulu-Natal', 'uMhlanga, alternatively rendered Umhlanga, is a residential, commercial and resort town north of Durban on the coast of KwaZulu-Natal, South Africa. It is part of the eThekwini Metropolitan Municipality, which was created in 2000 and includes the greater Durban area.', -29.73, 31.082778, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/UmhlangaKZN-pier.jpg/1920px-UmhlangaKZN-pier.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Andres de Wet', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:UmhlangaKZN-pier.jpg', 'https://en.wikipedia.org/wiki/UMhlanga%2C_KwaZulu-Natal'),
  ('Stellenbosch', 'stellenbosch', 'Western Cape', 'Stellenbosch is a town in the Western Cape province of South Africa, situated about 50 kilometres east of Cape Town, along the banks of the Eerste River at the foot of the Stellenbosch Mountain. The town became known as the City of Oaks or Eikestad in Afrikaans and Dutch due to the large number of oak trees that were planted by its founder, Simon van der Stel, to grace the streets and homesteads.', -33.934444, 18.869167, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Stellenbosch_aerial_photo_from_north-west_2024-01.jpg/1920px-Stellenbosch_aerial_photo_from_north-west_2024-01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'CJJ2501', 'CC0', 'https://commons.wikimedia.org/wiki/File:Stellenbosch_aerial_photo_from_north-west_2024-01.jpg', 'https://en.wikipedia.org/wiki/Stellenbosch'),
  ('Khayelitsha', 'khayelitsha', 'Western Cape', 'Khayelitsha is a township in Western Cape, South Africa, on the Cape Flats in the City of Cape Town Metropolitan Municipality. The name is Xhosa for New Home.', -34.040591, 18.66742, 'town', 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Khayelitsha_Lookout-Hill_Ilitha-Park.jpg/1920px-Khayelitsha_Lookout-Hill_Ilitha-Park.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'FreddieA', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Khayelitsha_Lookout-Hill_Ilitha-Park.jpg', 'https://en.wikipedia.org/wiki/Khayelitsha'),
  ('George', 'george', 'Western Cape', 'George is a city in the Western Cape province of South Africa. The city is a popular holiday and conference centre, as well as the administrative and commercial hub and the seat of the Garden Route District Municipality.', -33.959721, 22.458715, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/St._Marks_Anglican_Cathedral.jpg/1920px-St._Marks_Anglican_Cathedral.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Lugerda', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:St._Marks_Anglican_Cathedral.jpg', 'https://en.wikipedia.org/wiki/George%2C_South_Africa'),
  ('Gqeberha', 'gqeberha', 'Eastern Cape', 'Gqeberha, also known as Port Elizabeth and colloquially P.E.', -33.96186, 25.618673, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/4/4c/City_Hall_Port_Elizabeth-003.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Leo za1', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:City_Hall_Port_Elizabeth-003.jpg', 'https://en.wikipedia.org/wiki/Gqeberha'),
  ('East London', 'east-london', 'Eastern Cape', 'East London, officially KuGompo City since February 2026, is a city in the Buffalo City Metropolitan Municipality of the Eastern Cape Province, on the southeastern coast of South Africa. The city lies on the Indian Ocean coast, largely between the Buffalo River and the Nahoon River, and hosts the country''s only river port.', -33.01916, 27.899857, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/East_London%2C_Eastern_Cape%2C_South_Africa_%2820323340150%29.jpg/1920px-East_London%2C_Eastern_Cape%2C_South_Africa_%2820323340150%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:East_London,_Eastern_Cape,_South_Africa_(20323340150).jpg', 'https://en.wikipedia.org/wiki/East_London%2C_South_Africa'),
  ('Mthatha', 'mthatha', 'Eastern Cape', 'Mthatha, alternatively rendered Umtata, is the main city of the King Sabata Dalindyebo Local Municipality in Eastern Cape province of South Africa and the capital of OR Tambo District Municipality. The city has an airport, previously known as the K.', -31.589592, 28.787774, 'city', 9, 'https://upload.wikimedia.org/wikipedia/commons/5/56/Umtata.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', 'Uyingcwele', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Umtata.jpg', 'https://en.wikipedia.org/wiki/Mthatha'),
  ('Bloemfontein', 'bloemfontein', 'Free State', 'Bloemfontein, also known as Bloem, is the capital and the largest city of the Free State province in South Africa. It is often, and has been traditionally, referred to as the country''s "judicial capital", as it hosts the Supreme Court of Appeal, alongside the legislative capital Cape Town and executive capital Pretoria.', -29.116395, 26.215496, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Bloemfontein%2C_Free_State%2C_South_Africa_%2820349855518%29.jpg/1920px-Bloemfontein%2C_Free_State%2C_South_Africa_%2820349855518%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Bloemfontein,_Free_State,_South_Africa_(20349855518).jpg', 'https://en.wikipedia.org/wiki/Bloemfontein'),
  ('Kimberley', 'kimberley', 'Northern Cape', 'Kimberley  is the capital and largest city of the Northern Cape province of South Africa. It is located about 110 km (68 mi) east of the confluence of the Vaal and Orange Rivers.', -28.738301, 24.764225, 'city', 9, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Big_Hole%2C_Kimberley%2C_Northern_Cape%2C_South_Africa_%2820512571296%29.jpg/1920px-Big_Hole%2C_Kimberley%2C_Northern_Cape%2C_South_Africa_%2820512571296%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'South African Tourism from South Africa', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Big_Hole,_Kimberley,_Northern_Cape,_South_Africa_(20512571296).jpg', 'https://en.wikipedia.org/wiki/Kimberley%2C_South_Africa')
